-- Magic items retain their identity and inventory links. Mechanics use the ability contract.
INSERT INTO dndshare.item_type (id, name, parent_type_id, source_id, color, important, description, icon_image_id, cover_image_id)
SELECT 19, 'Магические предметы', 2, source_id, '#a78bfa', true,
       'Магическое снаряжение: свойства, настройка, заряды и зависимости на листе персонажа.', icon_image_id, cover_image_id
FROM dndshare.item_type WHERE id=2;

UPDATE dndshare.item_type SET fields =
  COALESCE((SELECT jsonb_agg(f ORDER BY n) FROM dndshare.item_type, jsonb_array_elements(fields) WITH ORDINALITY a(f,n) WHERE id=2 AND f->>'key'<>'type'), '[]'::jsonb)
  || $properties$[{"key":"type","name":"Вид предмета","type":"select","filter":true,"options":[{"value":"чудесный предмет","label":"Чудесный предмет"},{"value":"броня","label":"Броня"},{"value":"оружие","label":"Оружие"},{"value":"кольцо","label":"Кольцо"},{"value":"жезл","label":"Жезл"},{"value":"посох","label":"Посох"},{"value":"волшебная палочка","label":"Волшебная палочка"},{"value":"свиток","label":"Свиток"}]},{"key":"attunement","name":"Настройка на предмет","type":"select","default":"none","filter":true,"hint":"Настройка отмечается отдельно для каждого экземпляра в инвентаре. Требования проверяет игрок с мастером.","options":[{"value":"none","label":"Не требуется"},{"value":"required","label":"Требуется"},{"value":"unknown","label":"Нужно уточнить"}]},{"key":"attunement_requirement","name":"Кто может настроиться","type":"text","hint":"Например: заклинатель, паладин или существо доброго мировоззрения.","show_on":{"key":"attunement","value":"required"}},{"key":"activation","name":"Когда действуют свойства","type":"select","default":"equipped","hint":"Влияет на автоматические бонусы, действия и заклинания на листе. Настройка, если нужна, проверяется дополнительно.","options":[{"value":"equipped","label":"Когда экипирован / в руках"},{"value":"carried","label":"Пока находится в инвентаре"}]},{"key":"recharge_note","name":"Особое восстановление зарядов","type":"text","hint":"Например: на рассвете восстановить 1к6 + 1. Такие заряды меняются вручную; отдых не заменяет рассвет."}]$properties$::jsonb
  || COALESCE((SELECT jsonb_agg(f ORDER BY n) FROM dndshare.item_type, jsonb_array_elements(fields) WITH ORDINALITY a(f,n) WHERE id=12 AND f->>'key' IN ('category','required_armor_proficiency','strength_required','stealth_disadvantage')), '[]'::jsonb)
  || COALESCE((SELECT jsonb_agg(f ORDER BY n) FROM dndshare.item_type, jsonb_array_elements(fields) WITH ORDINALITY a(f,n) WHERE id=4 AND f->>'key' NOT IN ('desc','race_ids','subrace_ids','class_ids','subclass_ids')), '[]'::jsonb)
WHERE id=19;

