UPDATE dndshare.item i SET type_id=19, data=i.data::jsonb || a.properties
FROM audited a WHERE i.id=a.id AND i.name=a.expected_name AND i.type_id=2 AND i.user_id IS NULL;

UPDATE dndshare.item_type t SET count_items=(SELECT count(*) FROM dndshare.item i WHERE i.type_id=t.id AND i.user_id IS NULL) WHERE t.id IN (2,19);
SELECT setval(pg_get_serial_sequence('dndshare.item_type','id'), GREATEST(19,(SELECT max(id) FROM dndshare.item_type)), true);

-- Resolve proficiency by semantic name, not deployment-specific suggest IDs.
UPDATE dndshare.item i SET data=jsonb_set(i.data, '{required_armor_proficiency}', to_jsonb(s.id), true)
FROM dndshare.suggest s
WHERE i.type_id=19 AND i.user_id IS NULL AND i.id IN (92,112,304,1423)
AND s.type_id=3 AND s.user_id IS NULL
AND lower(s.value)=CASE WHEN i.id=1423 THEN lower('Лёгкие доспехи') ELSE lower('Щиты') END;

-- Each magical object has its own attunement and charges. Expand existing stacks
-- once while preserving item IDs, total quantity, placement and instance params.
CREATE FUNCTION dndshare.split_magic_item_stack(entries jsonb) RETURNS jsonb LANGUAGE sql AS $split$
  SELECT COALESCE(jsonb_agg(CASE WHEN i.id IS NULL THEN e ELSE
    e || jsonb_build_object('count',1,'uid',COALESCE(e->>'uid','magic-' || md5(e::text)) || CASE WHEN copy=1 THEN '' ELSE '-magic-' || copy::text END) END ORDER BY ord,copy), '[]'::jsonb)
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(entries)='array' THEN entries ELSE '[]'::jsonb END) WITH ORDINALITY rows(e,ord)
  LEFT JOIN dndshare.item i ON i.type_id=19 AND i.id::text=e->>'item_id'
  CROSS JOIN LATERAL generate_series(1, CASE WHEN i.id IS NOT NULL THEN GREATEST(1,COALESCE((e->>'count')::int,1)) ELSE 1 END) copy;
$split$;
UPDATE dndshare.char c SET data=jsonb_set(c.data,'{values,items}',
  (c.data#>'{values,items}') || jsonb_build_object(
    'equipped',dndshare.split_magic_item_stack(c.data#>'{values,items,equipped}'),
    'sections',COALESCE((SELECT jsonb_agg(s || jsonb_build_object('items',dndshare.split_magic_item_stack(s->'items')) ORDER BY ord)
      FROM jsonb_array_elements(COALESCE(c.data#>'{values,items,sections}','[]'::jsonb)) WITH ORDINALITY rows(s,ord)), '[]'::jsonb)))
WHERE jsonb_typeof(c.data#>'{values,items}')='object'
  AND EXISTS (SELECT 1 FROM jsonb_path_query(c.data#>'{values,items}', '$.**.item_id') refs(item_id) JOIN dndshare.item i ON i.id::text=refs.item_id#>>'{}' AND i.type_id=19);
DROP FUNCTION dndshare.split_magic_item_stack(jsonb);
